// 1D helper structures for k- and t-iterations (no actual data, only for traversal)
constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// initialization function
void init_array(auto A) {
	// A: i x j
	using namespace noarr;

	auto n = A | get_length<'i'>(); // matrix is n x n

	// Initialize A as unit-lower plus some values below diagonal, 0 above
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int nn = static_cast<int>(n);
		const int jj = static_cast<int>(j);

		if (j < i) {
			// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			num_t val = static_cast<num_t>((-jj % nn));
			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// Make the matrix positive semi-definite:
	// B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	auto B = noarr::bag(A.structure());

	// Zero B
	traverser(B).for_each([&](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	// Outer loop over t
	traverser(t_structure)
		.order(noarr::set_length<'t'>(n))
		.for_each([&](auto t_state) {
			auto t = get_index<'t'>(t_state);

			// Inner loops over r, s (i, j)
			traverser(B).for_each([&](auto rs_state) {
				auto [r, s] = get_indices<'i', 'j'>(rs_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				B[rs_state] += A[rt_state] * A[st_state];
			});
		});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
//
// Optimized version:
//  - Uses a single j-loop per row i, instead of two disjoint j-ranges.
//    This allows us to compute the common inner sum up to k < min(i, j)
//    and avoids creating two separate sliced traversers per row.
//  - Accumulates into a local variable `acc` for A[i][j] and writes it
//    back only once, instead of re-indexing A[i][j] on every k-iteration.
//    This reduces both memory traffic and Noarr indexing overhead.
//  - Reuses a single k-traverser with fixed maximum length n, and only
//    applies a cheap `slice<'k'>` per (i, j) to limit the k-range.
//
// Semantics are preserved: for each (i, j)
//   acc = A[i][j] - sum_{k < min(i, j)} A[i][k] * A[k][j]
//   if (j < i) acc /= A[j][j];
//
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	// Pre-build a 1D k-traverser with maximum length n.
	// For each (i, j) we will slice this to [0, min(i, j)) as needed.
	auto k_trav_full = traverser(k_structure).order(set_length<'k'>(n));

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'j' free
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// Traverse the whole row j = 0 .. n-1
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// trav_ij has both 'i' and 'j' fixed
			auto state_ij = trav_ij.state();
			auto j_idx = get_index<'j'>(state_ij);

			// Start from the current value of A[i][j]
			num_t acc = A[state_ij];

			// Common inner sum limit: k runs from 0 to min(i, j) - 1
			std::size_t limit = (j_idx < i_idx) ? j_idx : i_idx;

			if (limit > 0) {
				// Iterate k in [0, limit) by slicing the pre-built k-traverser
				auto trav_k = k_trav_full.order(slice<'k'>(0, limit));

				trav_k.for_each([&](auto k_state) {
					auto k_idx = get_index<'k'>(k_state);

					auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
					auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

					acc -= A[ik_state] * A[kj_state];
				});
			}

			// Lower-triangular part: j < i, divide by diagonal A[j][j]
			if (j_idx < i_idx) {
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				acc /= A[jj_state];
			}

			// Store the updated value back to A[i][j]
			A[state_ij] = acc;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

