// --------------------------------------------------------------------------
// computation kernel
//
// LU factorization without pivoting
//
// We keep the outer loop over i as in the original code, but we improve data
// locality in the second (upper-triangular) part by changing the loop order
// from (j outer, k inner) to (k outer, j inner). For each element A[i][j],
// the sequence of updates in k is preserved (k = 0..i-1 in both versions),
// so the floating-point result is bit-identical, while A[i][k] is now reused
// across all j for a fixed k, improving cache and register usage.
//
// All loop nests remain expressed using Noarr traversers.
// --------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	#pragma scop
	// Outer loop over row index i
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// View of the current row i (only dimension 'j')
		// This avoids repeatedly reconstructing ('i','j') states for A[i][*].
		auto row_i = A ^ noarr::fix<'i'>(i_idx);

		// ------------------------------------------------------------------
		// First inner loop: compute L(i, j) for 0 <= j < i
		// Original code (for each j):
		//   for (k = 0; k < j; k++)
		//     A[i][j] -= A[i][k] * A[k][j];
		//   A[i][j] /= A[j][j];
		// ------------------------------------------------------------------
		if (i_idx > 0) {
			// Restrict traversal to columns j < i
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				// 1D state for addressing row_i[j]
				auto j_state_1d = noarr::idx<'j'>(j_idx);

				// Forward substitution: A[i][j] -= sum_{k<j} A[i][k] * A[k][j]
				if (j_idx > 0) {
					traverser(k_structure)
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							// A[i][k] taken from the fixed row view
							auto k_state_1d = noarr::idx<'j'>(k_idx);
							num_t aik = row_i[k_state_1d];

							// A[k][j] uses the full 2D bag
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							// A[i][j] -= A[i][k] * A[k][j];
							row_i[j_state_1d] -= aik * A[kj_state];
						});
				}

				// A[i][j] /= A[j][j];
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				row_i[j_state_1d] /= A[jj_state];
			});
		}

		// ------------------------------------------------------------------
		// Second inner loop: compute U(i, j) for i <= j < n
		//
		// Original (for fixed i):
		//   for (j = i; j < n; j++)
		//     for (k = 0; k < i; k++)
		//       A[i][j] -= A[i][k] * A[k][j];
		//
		// New version:
		//   for (k = 0; k < i; k++) {
		//     aik = A[i][k];
		//     for (j = i; j < n; j++)
		//       A[i][j] -= aik * A[k][j];
		//   }
		//
		// For each fixed (i, j), the sequence of updates on A[i][j] with
		// respect to k is still k = 0..i-1 in both versions, so we preserve
		// exact floating point semantics. At the same time, we reuse A[i][k]
		// across all columns j, improving cache locality and reducing the
	// 	number of address computations for A[i][k].
		// ------------------------------------------------------------------
		auto len_second = n - i_idx;
		if (len_second > 0) {
			// Traverser over columns j >= i for this row
			auto trav_j_ge_i = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

