	// Make the matrix positive semi-definite:
	//   B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	//
	// We keep the logical order of accumulation:
	//   for t
	//     for r
	//       for s
	//         B[r][s] += A[r][t] * A[s][t];
	//
