// for (i=0; i<n; i++) {
//   for (j=0; j<i; j++) {
//     for (k=0; k<j; k++) A[i][j] -= A[i][k] * A[k][j];
//     A[i][j] /= A[j][j];
//   }
//   for (j=i; j<n; j++) {
//     for (k=0; k<i; k++) A[i][j] -= A[i][k] * A[k][j];
//   }
// }
//
// This implementation keeps exactly the same iteration order, but:
//   * reuses a pre-built 1D traverser for k
//   * uses the state coming from the traverser directly instead of
