	// Pre-build traversers that will be reused many times
	auto trav_A      = traverser(A);
	auto trav_k_base = traverser(k_structure);

	#pragma scop
	trav_A.template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx   = get_index<'i'>(state_i);

		// -----------------------------------------------------------------
		// First inner loop: 0 <= j < i
		// -----------------------------------------------------------------
		if (i_idx > 0) {
			// Create a view with j in [0, i_idx)
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				// This state already carries both 'i' and 'j'
				auto ij_state = trav_ij.state();
				auto j_idx    = get_index<'j'>(ij_state);

				// for (k = 0; k < j; k++)
				if (j_idx > 0) {
					auto trav_k = trav_k_base.order(noarr::set_length<'k'>(j_idx));

					trav_k.template for_dims<'k'>([&](auto trav_k_inner) {
						auto k_state = trav_k_inner.state();
						auto k_idx   = get_index<'k'>(k_state);

						auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
						auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

						A[ij_state] -= A[ik_state] * A[kj_state];
